/* Mi Espacio — aplicación local, sin servidor ni API */
(() => {
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const DAYS=['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'];
const SHORT=['L','M','X','J','V','S','D'];
const SUBJECTS=['Lengua','Tecnología','Matemáticas','Inglés','Historia','Piscina','Tutoría','Religión','Francés','Música','Geografía e Historia','Biología','Educación Física','Física y Química'];
const ORIGINAL=[
['08:15','Lengua','class'],['09:10','Tecnología','class'],['10:05','Matemáticas','class'],['11:00','Recreo','break'],['11:30','Inglés','class'],['12:25','Historia','class'],['15:15','Piscina','activity'],['16:15','Tutoría','class']
].map(x=>x);
const SCHEDULE={
'Lunes':ORIGINAL.map(x=>[...x]),
'Martes':[['08:15','Tecnología','class'],['09:10','Lengua','class'],['10:05','Religión','class'],['11:00','Recreo','break'],['11:30','Francés','class'],['12:25','Música','class'],['13:20','Matemáticas','class']],
'Miércoles':[['08:15','Geografía e Historia','class'],['09:10','Biología','class'],['10:05','Inglés','class'],['11:00','Recreo','break'],['11:30','Educación Física','class'],['12:25','Música','class'],['15:15','Física y Química','class'],['16:15','Lengua','class']],
'Jueves':[['08:15','Biología','class'],['09:10','Inglés','class'],['10:05','Matemáticas','class'],['11:00','Recreo','break'],['11:30','Religión','class'],['12:25','Lengua','class'],['13:20','Física y Química','class']],
'Viernes':[['08:15','Matemáticas','class'],['09:10','Física y Química','class'],['10:05','Francés','class'],['11:00','Recreo','break'],['11:30','Inglés','class'],['12:25','Geografía e Historia','class'],['13:20','Biología','class']]
};
const todayISO=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const dateISO=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const parseDate=s=>{const [y,m,d]=(s||todayISO()).split('-').map(Number);return new Date(y,m-1,d,12)};
const uid=()=>Math.random().toString(36).slice(2,9)+Date.now().toString(36).slice(-4);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=(s,opts={day:'numeric',month:'short'})=>s?parseDate(s).toLocaleDateString('es-ES',opts):'Sin fecha';
const dayDiff=s=>Math.round((parseDate(s)-parseDate(todayISO()))/86400000);
const monthName=d=>d.toLocaleDateString('es-ES',{month:'long',year:'numeric'});
const defaultState=()=>({
 version:1,profile:{name:'',setupComplete:false,quote:'No tienes que hacerlo todo hoy, solo dar el siguiente paso.'},
 books:{}, flashcards:[], rewards:0,
 tasks:[],habits:[{id:uid(),name:'Leer',active:true},{id:uid(),name:'Repasar lo aprendido',active:true},{id:uid(),name:'Preparar la mochila',active:true},{id:uid(),name:'Ordenar el escritorio',active:true},{id:uid(),name:'Beber agua',active:true},{id:uid(),name:'Dormir a una hora adecuada',active:true}],habitLogs:{},sessions:[],grades:[],
 schedule:JSON.parse(JSON.stringify(SCHEDULE)),settings:{theme:'light',background:'beige',weekStart:1,pomodoroStudy:25,pomodoroBreak:5,longBreak:15,longBreakEvery:4,notifications:false,quoteOn:true},
 timer:{mode:'study',duration:1500,remaining:1500,running:false,startedAt:null,sessionStart:null,subject:'',sessionsCount:0}
});
let state=loadState(),page='today',selectedBookSubject='',flashcardIndex=0,calendarDate=new Date(),selectedDate=todayISO(),selectedScheduleDay=DAYS[Math.max(0,Math.min(4,new Date().getDay()-1))]||'Lunes',timerInterval=null,toastTimer=null;
function loadState(){try{const s=JSON.parse(localStorage.getItem('miEspacioData'));if(s&&s.version===1)return {...defaultState(),...s,profile:{...defaultState().profile,...s.profile},books:s.books||{},flashcards:s.flashcards||[],settings:{...defaultState().settings,...s.settings},timer:{...defaultState().timer,...s.timer}}}catch(e){}return defaultState()}
function save(){try{localStorage.setItem('miEspacioData',JSON.stringify(state));return true}catch(e){toast('No se pudieron guardar los datos. Comprueba el espacio disponible.',true);return false}}
function toast(msg,error=false){const el=$('#toast');el.textContent=msg;el.className='toast'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',3000)}
function greeting(){let h=new Date().getHours();return h<12?'Buenos días':h<19?'Buenas tardes':'Buenas noches'}
function taskType(t){return ({exam:'Examen',task:'Tarea',homework:'Deberes',delivery:'Entrega',project:'Proyecto',presentation:'Presentación',event:'Evento escolar',other:'Otro'})[t]||'Tarea'}
function typeClass(t){return t==='exam'?'exam':(['delivery','event'].includes(t)?'event':'task')}
function taskDateLabel(t){if(!t.date)return 'Sin fecha';let d=dayDiff(t.date);return d<0?`Atrasada ${Math.abs(d)} d`:d===0?'Hoy':d===1?'Mañana':fmtDate(t.date,{day:'numeric',month:'short'})}
function eventsOn(date){return state.tasks.filter(t=>t.date===date)}
function upcomingTasks(days=14){return state.tasks.filter(t=>t.date&&t.date>=todayISO()&&dayDiff(t.date)<=days&&t.status!=='completed').sort((a,b)=>a.date.localeCompare(b.date)||(a.time||'').localeCompare(b.time||''))}
function exams(){return state.tasks.filter(t=>t.type==='exam').sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999'))}
function completedToday(){return state.tasks.filter(t=>t.date===todayISO()&&t.status==='completed').length}
function pendingToday(){return state.tasks.filter(t=>t.date===todayISO()&&t.status!=='completed').length}
function studySeconds(){return state.sessions.reduce((n,s)=>n+(s.seconds||0),0)}
function mins(n){return `${Math.floor(n/60)} h ${Math.round(n%60)} min`}
function normalizedGrade(g){return Number(g.score)/Number(g.max)*10}
function averages(){let map={};state.grades.forEach(g=>{(map[g.subject]??=[]).push(normalizedGrade(g))});Object.keys(map).forEach(k=>map[k]=map[k].reduce((a,b)=>a+b,0)/map[k].length);return map}
function subjectNames(){return [...new Set([...SUBJECTS,...state.schedule?Object.values(state.schedule).flat().map(c=>c[1]):[],...state.tasks.map(t=>t.subject).filter(Boolean),...state.grades.map(g=>g.subject).filter(Boolean),...state.sessions.map(s=>s.subject).filter(Boolean)])].filter(Boolean)}
function header(eyebrow,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc||''}</p></div>${action}</div>`}
function cardHead(title,action=''){return `<div class="card-head"><h2>${title}</h2>${action}</div>`}
function stat(label,value,foot,icon){return `<div class="card stat-card"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot||''}</div></div>`}
function empty(title,desc){return `<div class="empty"><strong>${title}</strong>${desc||''}</div>`}
function taskRow(t,opts={}){let done=t.status==='completed';return `<div class="task-row ${done?'completed':''}"><input class="check" type="checkbox" ${done?'checked':''} data-action="toggle-task" data-id="${t.id}" aria-label="Marcar como completada"><div class="row-main"><div class="row-title">${esc(t.title)}</div><div class="row-sub">${esc(t.subject||'Sin asignatura')} · ${t.date?esc(fmtDate(t.date,{weekday:'short',day:'numeric',month:'short'})):'Sin fecha'}${t.time?' · '+esc(t.time):''}</div></div><span class="pill ${t.priority||'medium'}">${t.priority==='high'?'Alta':t.priority==='low'?'Baja':'Media'}</span><div class="row-actions"><button class="icon-btn" data-action="edit-task" data-id="${t.id}" aria-label="Editar">✎</button><button class="icon-btn" data-action="delete-task" data-id="${t.id}" aria-label="Eliminar">×</button></div></div>`}
function eventRow(t){let d=dayDiff(t.date);return `<div class="event-row"><div class="stat-icon">${t.type==='exam'?'✎':t.type==='delivery'?'↗':'◷'}</div><div class="row-main"><div class="row-title">${esc(t.title)}</div><div class="row-sub">${esc(taskType(t.type))} · ${esc(t.subject||'General')} · ${fmtDate(t.date,{weekday:'short',day:'numeric',month:'short'})}</div></div>${t.type==='exam'?`<span class="pill exam">${d<0?'Pasado':d===0?'Hoy':d===1?'Mañana':`Faltan ${d} días`}</span>`:`<span class="pill ${typeClass(t.type)}">${taskDateLabel(t)}</span>`}</div>`}
function renderToday(){let todayTasks=state.tasks.filter(t=>t.date===todayISO()).sort((a,b)=>(a.time||'').localeCompare(b.time||''));let next=upcomingTasks(30);let habits=state.habits.filter(h=>h.active);let checked=habits.filter(h=>(state.habitLogs[todayISO()]||[]).includes(h.id)).length;let all=state.tasks.filter(t=>t.date===todayISO()).length;let done=completedToday();let percent=all?Math.round(done/all*100):0;let nextClass=getNextClass();let quote=state.settings.quoteOn?`<p>${esc(state.profile.quote||'')}</p>`:'';return `${`<section class="card welcome"><div class="date-line">${new Date().toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).toUpperCase()}</div><h1>${greeting()}, ${esc(state.profile.name||'estudiante')} ✨</h1>${quote}</section>`}
<div class="grid four">${stat('Tareas pendientes',state.tasks.filter(t=>t.status!=='completed'&&(!t.date||t.date>=todayISO())).length,'Por hacer','☷')}${stat('Completadas hoy',done,all?`${percent}% de las tareas de hoy`:'Sin tareas para hoy','✓')}${stat('Próximos exámenes',exams().filter(t=>t.date&&t.date>=todayISO()&&t.status!=='completed').length,'En tu lista','✎')}${stat('Tiempo de estudio',mins(Math.round(studySeconds()/60)),`${state.sessions.length} sesiones registradas`,'◷')}</div>
<div class="grid two section-gap"><section class="card">${cardHead('Mis tareas de hoy',`<button class="button small" data-action="new-task">+ Añadir</button>`)}${todayTasks.length?todayTasks.map(t=>taskRow(t)).join(''):empty('Un día despejado','Añade una tarea con fecha de hoy y aparecerá aquí.')}<div style="margin-top:15px"><div class="row-sub" style="margin-bottom:8px">Progreso de hoy <b style="float:right;color:#777">${percent}%</b></div><div class="progress"><span style="width:${percent}%"></span></div></div></section>
<section class="card">${cardHead('Lo que viene',`<button class="button small" data-page="tasks">Ver todo →</button>`)}${next.slice(0,4).length?next.slice(0,4).map(eventRow).join(''):empty('Todavía no hay eventos','Los exámenes y las entregas que añadas aparecerán aquí.')}<div class="notice" style="margin-top:15px">✧ ${nextClass?`<b>Próxima clase:</b> ${esc(nextClass.subject)} · ${esc(nextClass.time)} (${esc(nextClass.day)})`:'<b>Tu horario está a mano.</b> Consulta Mi horario para ver tus clases.'}</div></section></div>
<div class="grid two section-gap"><section class="card">${cardHead('Hábitos de hoy',`<button class="button small" data-page="habits">Ver hábitos →</button>`)}${habits.length?habits.slice(0,5).map(h=>`<div class="habit-row"><input class="check" type="checkbox" data-action="toggle-habit" data-id="${h.id}" ${(state.habitLogs[todayISO()]||[]).includes(h.id)?'checked':''}><div class="row-main"><div class="row-title">${esc(h.name)}</div></div><span class="small-muted">${(state.habitLogs[todayISO()]||[]).includes(h.id)?'Hecho':'Pendiente'}</span></div>`).join(''):empty('Sin hábitos todavía','Puedes crear tus propios hábitos.')}<div class="row-sub" style="margin-top:12px">${checked} de ${habits.length} hábitos completados</div><div class="progress" style="margin-top:7px"><span style="width:${habits.length?checked/habits.length*100:0}%"></span></div></section>
<section class="card reward-card">${cardHead('Tus pequeños logros')}<div class="reward-stars">${'★'.repeat(Math.min(5,Math.floor(state.tasks.filter(t=>t.status==='completed').length/3))||1)}<span>✧</span></div><b>${state.tasks.filter(t=>t.status==='completed').length} tareas completadas</b><p class="muted">Cada tres tareas terminadas sumas una estrella. ¡Sigue así!</p><div class="progress"><span style="width:${Math.min(100,state.tasks.filter(t=>t.status==='completed').length/3*20)}%"></span></div></section><section class="card">${cardHead('Un pequeño recordatorio')}<div style="font:700 18px Manrope;line-height:1.45;margin:10px 0 12px">Lo importante es avanzar, no hacerlo perfecto.</div><p class="muted" style="line-height:1.7;font-size:12px">Organiza tu día con calma. Cada tarea que terminas y cada pausa que te das también cuentan.</p><button class="button soft" data-page="study">Empezar a estudiar ↗</button></section></div>`}
function renderTasks(){const q=window.taskSearch||'',type=window.taskFilterType||'',status=window.taskFilterStatus||'',sub=window.taskFilterSubject||'';let list=state.tasks.filter(t=>(!q||`${t.title} ${t.description||''}`.toLowerCase().includes(q.toLowerCase()))&&(!type||t.type===type)&&(!status||t.status===status)&&(!sub||t.subject===sub)).sort((a,b)=>{if(a.status==='completed'&&b.status!=='completed')return 1;if(b.status==='completed'&&a.status!=='completed')return -1;return (a.date||'9999').localeCompare(b.date||'9999')});return `${header('ORGANÍZATE','Tareas y exámenes','Todo lo que tienes pendiente, en un solo lugar.',`<button class="button primary" data-action="new-task">＋ Añadir elemento</button>`)}
<div class="toolbar"><input id="taskSearch" placeholder="Buscar por título o descripción…" value="${esc(q)}"><select id="taskFilterType"><option value="">Todos los tipos</option>${[['task','Tarea'],['homework','Deberes'],['exam','Examen'],['delivery','Entrega'],['project','Proyecto'],['presentation','Presentación'],['event','Evento escolar'],['other','Otro']].map(([v,l])=>`<option value="${v}" ${type===v?'selected':''}>${l}</option>`).join('')}</select><select id="taskFilterSubject"><option value="">Todas las asignaturas</option>${subjectNames().map(s=>`<option ${sub===s?'selected':''}>${esc(s)}</option>`).join('')}</select><select id="taskFilterStatus"><option value="">Todos los estados</option><option value="pending" ${status==='pending'?'selected':''}>Pendiente</option><option value="inprogress" ${status==='inprogress'?'selected':''}>En curso</option><option value="completed" ${status==='completed'?'selected':''}>Completado</option></select></div>
<div class="grid three" style="margin-bottom:17px">${stat('Pendientes',state.tasks.filter(t=>t.status!=='completed').length,'Sin terminar','☷')}${stat('Atrasadas',state.tasks.filter(t=>t.date&&t.date<todayISO()&&t.status!=='completed').length,'Revisa las fechas','!')}${stat('Exámenes',exams().filter(t=>t.date&&t.date>=todayISO()&&t.status!=='completed').length,'Próximos','✎')}</div>
<section class="card">${cardHead(`Elementos (${list.length})`)}${list.length?list.map(t=>`<div>${taskRow(t)}<div class="row-sub" style="padding-left:30px;margin-top:-6px;margin-bottom:5px"><span class="pill ${typeClass(t.type)}">${taskType(t.type)}</span> <span class="pill ${t.status==='completed'?'done':''}">${t.status==='completed'?'Completado':t.status==='inprogress'?'En curso':'Pendiente'}</span>${t.description?` ${esc(t.description)}`:''}${t.type==='exam'&&t.date?` · <b>${dayDiff(t.date)<0?'Examen pasado':dayDiff(t.date)===0?'Es hoy':dayDiff(t.date)===1?'Mañana':`Faltan ${dayDiff(t.date)} días`}</b>`:''}</div></div>`).join(''):empty('No hay elementos que mostrar','Crea una tarea o cambia los filtros para ver tus elementos.')}</section>`}
function renderCalendar(){let y=calendarDate.getFullYear(),m=calendarDate.getMonth(),first=new Date(y,m,1),offset=(first.getDay()+6)%7,start=new Date(y,m,1-offset);let cells='';for(let i=0;i<42;i++){let d=new Date(start);d.setDate(start.getDate()+i);let iso=dateISO(d),ev=eventsOn(iso);cells+=`<button class="day-cell ${d.getMonth()!==m?'outside':''} ${iso===todayISO()?'today':''} ${iso===selectedDate?'selected':''}" data-action="select-date" data-date="${iso}"><div class="day-num">${d.getDate()}</div>${ev.slice(0,2).map(t=>`<div class="day-event ${typeClass(t.type)}">${esc(t.title)}</div>`).join('')}${ev.length>2?`<div class="more-events">+${ev.length-2} más</div>`:''}</button>`}
let selected=eventsOn(selectedDate).sort((a,b)=>(a.time||'').localeCompare(b.time||''));return `${header('PLANIFICA CON CALMA','Calendario','Tu mes de un vistazo. Las tareas y los exámenes aparecen aquí automáticamente.',`<button class="button primary" data-action="new-task" data-date="${selectedDate}">＋ Añadir evento</button>`)}
<section class="card"><div class="card-head"><div class="calendar-top"><button class="button small" data-action="prev-month">‹</button><h2>${monthName(calendarDate).replace(/^\w/,c=>c.toUpperCase())}</h2><button class="button small" data-action="next-month">›</button></div><button class="button small" data-action="current-month">Hoy</button></div><div class="calendar-grid">${DAYS.map(d=>`<div class="weekday">${d.slice(0,3)}</div>`).join('')}${cells}</div><div class="row-sub" style="margin-top:14px"><span class="pill task">Tareas y entregas</span> <span class="pill exam">Exámenes</span> <span class="pill event">Eventos</span></div></section>
<section class="card day-detail">${cardHead(`📅 ${fmtDate(selectedDate,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}`,`<button class="button small" data-action="new-task" data-date="${selectedDate}">＋ Añadir</button>`)}${selected.length?selected.map(t=>`<div>${eventRow(t)}<div class="row-actions" style="justify-content:flex-end;margin-top:-5px"><button class="button small" data-action="edit-task" data-id="${t.id}">Editar</button><button class="button small danger" data-action="delete-task" data-id="${t.id}">Eliminar</button></div></div>`).join(''):empty('Día sin eventos','No hay tareas ni eventos registrados para esta fecha.')}</section>`}
function renderHabits(){let active=state.habits.filter(h=>h.active),logs=state.habitLogs[todayISO()]||[],done=active.filter(h=>logs.includes(h.id)).length;let last7=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let iso=dateISO(d),l=state.habitLogs[iso]||[];return {iso,label:d.toLocaleDateString('es-ES',{weekday:'short'}).replace('.',''),pct:active.length?Math.round(active.filter(h=>l.includes(h.id)).length/active.length*100):0}});return `${header('PEQUEÑOS PASOS','Hábitos','La constancia se construye con pequeños gestos.',`<button class="button primary" data-action="new-habit">＋ Nuevo hábito</button>`)}
<div class="grid two"><section class="card">${cardHead('Hoy',`${done}/${active.length} completados`)}<div class="progress" style="margin-bottom:14px"><span style="width:${active.length?done/active.length*100:0}%"></span></div>${active.length?active.map(h=>`<div class="habit-row"><input class="check" type="checkbox" data-action="toggle-habit" data-id="${h.id}" ${logs.includes(h.id)?'checked':''}><div class="row-main"><div class="row-title">${esc(h.name)}</div><div class="row-sub">${logs.includes(h.id)?'¡Hecho por hoy!':'Cada pequeño paso cuenta'}</div></div><button class="icon-btn" data-action="edit-habit" data-id="${h.id}" aria-label="Editar hábito">✎</button><button class="icon-btn" data-action="delete-habit" data-id="${h.id}" aria-label="Eliminar hábito">×</button></div>`).join(''):empty('Empieza con un hábito','Añade algo pequeño que te gustaría incorporar a tu rutina.')}</section>
<section class="card">${cardHead('Constancia de los últimos 7 días')}<div class="chart-bars">${last7.map(d=>`<div class="chart-col"><div class="bar" style="height:${Math.max(2,d.pct)}%"></div><label>${esc(d.label)}</label></div>`).join('')}</div><div class="small-muted" style="margin-top:12px">El gráfico muestra el porcentaje de hábitos activos completados cada día.</div></section></div>
<section class="card section-gap">${cardHead('Historial por hábito')} ${state.habits.length?state.habits.map(h=>`<div class="habit-row"><div class="row-main"><div class="row-title">${esc(h.name)} ${h.active?'':'<span class="pill">Archivado</span>'}</div><div class="row-sub">${habitStreak(h.id)} días de racha actual · ${Object.values(state.habitLogs).filter(a=>a.includes(h.id)).length} días completados en total</div></div><button class="button small" data-action="habit-history" data-id="${h.id}">Ver historial</button></div>`).join(''):empty('Aún no hay hábitos','Crea uno para empezar a registrar tu constancia.')}</section>`}
function habitStreak(id){let n=0,d=parseDate(todayISO());while(true){let iso=dateISO(d);if(!(state.habitLogs[iso]||[]).includes(id)){if(n===0){d.setDate(d.getDate()-1);iso=dateISO(d);if(!(state.habitLogs[iso]||[]).includes(id))break;}else break}if((state.habitLogs[iso]||[]).includes(id))n++;d.setDate(d.getDate()-1);if(n>3650)break}return n}
function renderStudy(){let t=state.timer;let remain=t.running&&t.startedAt?t.remaining-Math.max(0,Math.floor((Date.now()-t.startedAt)/1000)):t.remaining;remain=Math.max(0,remain);return `${header('CONCENTRACIÓN','Modo estudio','Reserva un ratito para ti y céntrate en una cosa cada vez.')}
<div class="grid two"><section class="card"><div style="text-align:center"><div class="eyebrow">${t.mode==='study'?'TIEMPO DE ESTUDIO':t.mode==='break'?'DESCANSO':'DESCANSO LARGO'}</div><div class="timer-face" id="timerFace">${String(Math.floor(remain/60)).padStart(2,'0')}:${String(remain%60).padStart(2,'0')}</div><div class="timer-caption" id="timerCaption">${t.running?'Sesión en curso':t.mode==='study'?'Todo listo para concentrarte':'Tómate un respiro'}</div><div class="timer-controls"><button class="button primary" data-action="timer-toggle">${t.running?'Ⅱ Pausar':'▶ '+(t.remaining<t.duration?'Reanudar':'Empezar')}</button><button class="button" data-action="timer-reset">↺ Reiniciar</button></div><div class="timer-settings"><label class="small-muted">Duración (min)</label><input type="number" id="timerMinutes" min="1" max="180" value="${Math.max(1,Math.round(t.duration/60))}" ${t.running?'disabled':''}><select id="timerSubject" ${t.running?'disabled':''}><option value="">Sin asignatura</option>${subjectNames().map(s=>`<option ${t.subject===s?'selected':''}>${esc(s)}</option>`).join('')}</select><button class="button small" data-action="timer-apply" ${t.running?'disabled':''}>Aplicar</button></div><div class="small-muted" style="margin-top:16px">Pomodoro: ${state.settings.pomodoroStudy} min de estudio · ${state.settings.pomodoroBreak} min de descanso</div><div class="focus-tools"><button class="button" data-action="focus-mode">☾ Modo concentración</button><button class="button" data-action="sound-toggle" id="soundToggle">♫ Sonido ambiente</button></div><p class="small-muted" style="text-align:center">Activa el modo concentración para ocultar distracciones visuales. El sonido ambiente se genera en este dispositivo.</p></div></section>
<section class="card">${cardHead('Tu tiempo de estudio')}<div class="grid two">${stat('Tiempo total',mins(Math.round(studySeconds()/60)),'Sesiones guardadas','◷')}${stat('Sesiones',state.sessions.length,'Completadas','✓')}</div><div class="notice" style="margin-top:15px">Cuando el temporizador llega a cero, la sesión se guarda y aparece en el historial. El tiempo se recupera al recargar la página.</div><div style="margin-top:20px">${cardHead('Últimas sesiones')}${state.sessions.slice().reverse().slice(0,5).map(s=>`<div class="session-row"><div class="stat-icon">◷</div><div class="row-main"><div class="row-title">${esc(s.subject||'Estudio libre')}</div><div class="row-sub">${fmtDate(s.date,{day:'numeric',month:'short'})} · ${s.mode==='study'?'Estudio':'Sesión'} </div></div><b>${mins(Math.round((s.seconds||0)/60))}</b></div>`).join('')||empty('Tu historial empezará aquí','Completa una sesión para ver tu tiempo acumulado.')}</div></section></div>`}
function renderGrades(){let sub=window.gradeFilter||'',list=state.grades.filter(g=>!sub||g.subject===sub).sort((a,b)=>(b.date||'').localeCompare(a.date||'')),avg=averages(),vals=Object.values(avg),overall=vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null;return `${header('TU RECORRIDO','Registro de notas','Registra tus calificaciones y consulta tus medias reales.',`<button class="button primary" data-action="new-grade">＋ Añadir nota</button>`)}
<div class="grid three" style="margin-bottom:17px">${stat('Notas registradas',state.grades.length,'En tu historial','✎')}${stat('Media general',overall===null?'—':overall.toFixed(2)+'/10',overall===null?'Añade notas para calcularla':'Media de las medias por asignatura','◎')}${stat('Asignaturas',Object.keys(avg).length,'Con calificaciones','▤')}</div>
<section class="card">${cardHead('Media por asignatura')}${Object.keys(avg).length?Object.entries(avg).sort((a,b)=>a[0].localeCompare(b[0])).map(([s,v])=>`<div class="bar-row"><span>${esc(s)}</span><div class="progress"><span style="width:${Math.max(0,Math.min(100,v*10))}%"></span></div><span class="value">${v.toFixed(2)}/10</span></div>`).join(''):empty('Aún no hay medias','Cuando registres calificaciones, aquí verás la media normalizada sobre 10.')}</section>
<section class="card section-gap">${cardHead('Historial de calificaciones')}<div class="toolbar"><select id="gradeFilter"><option value="">Todas las asignaturas</option>${subjectNames().map(s=>`<option ${sub===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div>${list.length?list.map(g=>`<div class="grade-row"><div class="stat-icon">✎</div><div class="row-main"><div class="row-title">${esc(g.title)}</div><div class="row-sub">${esc(g.subject)} · ${fmtDate(g.date,{day:'numeric',month:'short',year:'numeric'})}${g.comments?' · '+esc(g.comments):''}</div></div><div class="grade-number">${Number(g.score).toLocaleString('es-ES')}<small> / ${Number(g.max).toLocaleString('es-ES')}</small></div><span class="pill">${normalizedGrade(g).toFixed(2)}/10</span><button class="icon-btn" data-action="edit-grade" data-id="${g.id}">✎</button><button class="icon-btn" data-action="delete-grade" data-id="${g.id}">×</button></div>`).join(''):empty('Todavía no has registrado notas','Añade una calificación para empezar a ver tu evolución.')}</section>`}
function renderStats(){let total=state.tasks.length,done=state.tasks.filter(t=>t.status==='completed').length,avg=averages(),subjects=Object.entries(avg),week=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let iso=dateISO(d);return {iso,label:d.toLocaleDateString('es-ES',{weekday:'short'}).replace('.',''),n:state.sessions.filter(s=>s.date===iso).reduce((n,s)=>n+s.seconds,0)}});let max=Math.max(1,...week.map(d=>d.n));let taskWeek=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let iso=dateISO(d);return {label:d.toLocaleDateString('es-ES',{weekday:'short'}).replace('.',''),n:state.tasks.filter(t=>t.date===iso&&t.status==='completed').length}}),maxTasks=Math.max(1,...taskWeek.map(d=>d.n));let habitCount=Object.values(state.habitLogs).flat().length;return `${header('MIRA LO QUE HAS LOGRADO','Progreso y estadísticas','Datos reales de tu actividad. Cada registro cuenta.')}
<div class="grid four">${stat('Tareas totales',total,'Registradas','☷')}${stat('Completadas',done,`${total?Math.round(done/total*100):0}% del total`,'✓')}${stat('Tiempo de estudio',mins(Math.round(studySeconds()/60)),`${state.sessions.length} sesiones`,'◷')}${stat('Hábitos completados',habitCount,'Registros acumulados','♡')}</div>
<div class="grid two section-gap"><section class="card">${cardHead('Tiempo de estudio · 7 días')}${state.sessions.length?`<div class="chart-bars">${week.map(d=>`<div class="chart-col"><div class="bar" title="${mins(Math.round(d.n/60))}" style="height:${Math.max(2,d.n/max*100)}%"></div><label>${esc(d.label)}</label></div>`).join('')}</div><div class="small-muted" style="margin-top:12px">Total en el periodo: ${mins(Math.round(week.reduce((n,d)=>n+d.n,0)/60))}</div>`:empty('Tu gráfica está esperando','Completa sesiones de estudio para ver aquí tu actividad.')}</section>
<section class="card">${cardHead('Tareas completadas · 7 días')}${state.tasks.some(t=>t.status==='completed')?`<div class="chart-bars">${taskWeek.map(d=>`<div class="chart-col"><div class="bar" style="height:${Math.max(2,d.n/maxTasks*100)}%"></div><label>${esc(d.label)}</label></div>`).join('')}</div><div class="small-muted" style="margin-top:12px">Tareas completadas durante los últimos siete días.</div>`:empty('Todavía no hay tareas completadas','Marca una tarea como completada para empezar a ver tu progreso.')}</section></div>
<div class="grid two section-gap"><section class="card">${cardHead('Notas por asignatura')}${subjects.length?subjects.map(([s,v])=>`<div class="bar-row"><span>${esc(s)}</span><div class="progress"><span style="width:${v*10}%"></span></div><span class="value">${v.toFixed(2)}</span></div>`).join(''):empty('Sin calificaciones','Registra notas para consultar tus medias.')}</section>
<section class="card">${cardHead('Hábitos y constancia')}<div class="stat-value" style="margin:15px 0 8px">${habitCount}</div><div class="muted" style="font-size:12px">marcas de hábitos en total</div><div class="notice" style="margin-top:17px">${state.habits.length?'Tu registro diario irá construyendo un historial de constancia.':'Crea hábitos y marca los días que los completas para empezar.'}</div></section></div>`}
function getNextClass(){let now=new Date(),day=now.getDay();if(day===0||day===6)return null;let dayName=DAYS[day-1],classes=state.schedule[dayName]||[];let current=now.getHours()*60+now.getMinutes();for(let c of classes){let [h,m]=c[0].split(':').map(Number);if(h*60+m>current)return {day:dayName,time:c[0],subject:c[1]}}for(let i=1;i<=5;i++){let idx=(day-1+i)%5,dn=DAYS[idx],list=state.schedule[dn]||[];let next=list.find(c=>c[2]!=='break');if(next)return {day:dn,time:next[0],subject:next[1]}}return null}
function renderSchedule(){let days=DAYS.slice(0,5),all=days.flatMap(d=>(state.schedule[d]||[]).map(c=>c[0])).filter(Boolean),times=[...new Set(all)].sort();return `${header('TU SEMANA','Mi horario','Tu horario fijo, editable y separado de las tareas y los exámenes.',`<button class="button" data-action="reset-schedule">↺ Restaurar original</button>`)}
<div class="week-tabs" style="margin-bottom:15px">${days.map(d=>`<button class="${selectedScheduleDay===d?'active':''}" data-action="schedule-day" data-day="${d}">${d}</button>`).join('')}</div>
<section class="card">${cardHead(`Horario del ${selectedScheduleDay.toLowerCase()}`,`<button class="button primary small" data-action="new-class">＋ Añadir clase</button>`)}${(state.schedule[selectedScheduleDay]||[]).length?`<div class="week-grid"><table class="schedule-table" style="min-width:0"><thead><tr><th style="text-align:left">Hora</th><th style="text-align:left">Clase / actividad</th><th></th></tr></thead><tbody>${(state.schedule[selectedScheduleDay]||[]).slice().sort((a,b)=>a[0].localeCompare(b[0])).map((c,i)=>`<tr><td class="time-cell">${esc(c[0])}</td><td><div class="class-block ${c[2]==='activity'?'activity':c[2]==='break'?'break':''}">${esc(c[1])}<small>${c[2]==='activity'?'Actividad extraescolar':c[2]==='break'?'Descanso':'Clase'}</small></div></td><td style="background:transparent;vertical-align:middle"><button class="icon-btn" data-action="edit-class" data-day="${selectedScheduleDay}" data-index="${i}">✎</button><button class="icon-btn" data-action="delete-class" data-day="${selectedScheduleDay}" data-index="${i}">×</button></td></tr>`).join('')}</tbody></table></div>`:empty('Este día no tiene clases registradas','Puedes añadir una clase si necesitas personalizar el horario.')}<div class="notice" style="margin-top:15px">El recreo y las actividades extraescolares se mantienen en el horario, pero no cuentan como tareas ni como eventos del calendario.</div></section>
<section class="card section-gap">${cardHead('Vista semanal')}<div class="week-grid"><table class="schedule-table"><thead><tr><th>Hora</th>${days.map(d=>`<th>${d}</th>`).join('')}</tr></thead><tbody>${times.map(time=>`<tr><td class="time-cell">${time}</td>${days.map(d=>{let c=(state.schedule[d]||[]).find(x=>x[0]===time);return `<td>${c?`<div class="class-block ${c[2]==='activity'?'activity':c[2]==='break'?'break':''}">${esc(c[1])}</div>`:''}</td>`}).join('')}</tr>`).join('')}</tbody></table></div></section>`}
let ambientContext=null,ambientNode=null,ambientGain=null;function toggleAmbientSound(btn){if(ambientContext){try{ambientNode.stop()}catch(e){}ambientContext.close();ambientContext=null;ambientNode=null;btn.textContent='♫ Sonido ambiente';toast('Sonido ambiente apagado');return}try{const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx)throw new Error();ambientContext=new Ctx();const buffer=ambientContext.createBuffer(1,ambientContext.sampleRate*2,ambientContext.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.12;ambientNode=ambientContext.createBufferSource();ambientNode.buffer=buffer;ambientNode.loop=true;const filter=ambientContext.createBiquadFilter();filter.type='lowpass';filter.frequency.value=520;ambientGain=ambientContext.createGain();ambientGain.gain.value=.08;ambientNode.connect(filter);filter.connect(ambientGain);ambientGain.connect(ambientContext.destination);ambientNode.start();btn.textContent='♫ Apagar sonido';toast('Sonido ambiente activado')}catch(e){toast('Tu navegador no permite generar sonido ambiente.',true)}}
const BOOK_ICONS={'Lengua':'Aa','Tecnología':'⌘','Matemáticas':'∑','Inglés':'EN','Historia':'⌛','Piscina':'≋','Tutoría':'♡','Religión':'✧','Francés':'FR','Música':'♫','Geografía e Historia':'◎','Biología':'❀','Educación Física':'↗','Física y Química':'⚗'};
const BACKGROUNDS=[['rosa','Rosa palo'],['glitter','Rosa palo con purpurina'],['azul','Azul claro'],['verde','Verde claro'],['beige','Beige'],['morado','Morado']];
function showOnboarding(){if($('#welcomeSetup'))return;$('#modalRoot').innerHTML=`<div class="onboarding-backdrop" id="welcomeSetup"><section class="onboarding"><div class="onboarding-mark">m.</div><div class="eyebrow">TU ESPACIO PERSONAL</div><h1>Vamos a prepararlo<br>a tu manera.</h1><p>Antes de empezar, dinos cómo quieres que te llamemos y elige tu color de fondo.</p><form id="welcomeForm"><div class="field"><label>¿Cómo quieres que te llame?</label><input name="name" maxlength="50" placeholder="Escribe tu nombre" required autofocus></div><div class="field"><label>Elige tu fondo</label><div class="background-options">${BACKGROUNDS.map(([id,label])=>`<label class="bg-option"><input type="radio" name="background" value="${id}" ${id==='beige'?'checked':''}><span class="swatch swatch-${id}"></span><small>${label}</small></label>`).join('')}</div></div><button class="button primary" type="submit" style="width:100%;margin-top:10px">Entrar en mi espacio →</button></form><small class="privacy-note">Tus preferencias se guardan en este navegador.</small></section></div>`;$('#welcomeForm').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget);state.profile.name=String(fd.get('name')||'').trim()||'Estudiante';state.profile.setupComplete=true;state.settings.background=fd.get('background')||'beige';save();$('#modalRoot').innerHTML='';render();toast(`¡Bienvenida/o, ${state.profile.name}!`)})}
function renderShelf(){let subjects=subjectNames();return `${header('TU BIBLIOTECA','Estantería de asignaturas','Cada libro guarda tus esquemas, resúmenes y documentos.',`<button class="button primary" data-action="new-book-subject">＋ Nueva asignatura</button>`)}<section class="card bookshelf-intro"><div><div class="eyebrow">TU COLECCIÓN</div><h2>Una estantería para cada materia.</h2><p>Abre un libro para consultar lo que has guardado o añadir nuevos apuntes.</p></div><div class="bookshelf-count"><b>${Object.values(state.books).reduce((n,a)=>n+a.length,0)}</b><small>documentos guardados</small></div></section><div class="bookshelf-grid">${subjects.map((sub,i)=>{let count=(state.books[sub]||[]).length;return `<button class="subject-book book-${i%6}" data-action="open-book" data-subject="${esc(sub)}"><span class="book-spine"></span><span class="book-icon">${BOOK_ICONS[sub]||sub.slice(0,2).toUpperCase()}</span><b>${esc(sub)}</b><small>${count} ${count===1?'documento':'documentos'}</small><span class="book-open">Abrir libro ↗</span></button>`}).join('')}</div><div class="notice section-gap">Consejo: puedes adjuntar PDF, imágenes, documentos de texto y otros archivos. Los archivos se guardan en este navegador; exporta una copia de seguridad con frecuencia.</div>`}
function renderBook(){let sub=selectedBookSubject,items=state.books[sub]||[];return `${header('ESTANTERÍA',esc(sub),'Tus apuntes y materiales de esta asignatura.',`<button class="button" data-action="back-shelf">← Volver a la estantería</button><button class="button primary" data-action="attach-book-file">＋ Adjuntar archivo</button>`)}<section class="card book-detail-head"><div class="large-book-mark">${BOOK_ICONS[sub]||'Aa'}</div><div><div class="eyebrow">MI LIBRO DE</div><h2>${esc(sub)}</h2><p>${items.length} archivos guardados. Puedes añadir esquemas, resúmenes y documentos para consultarlos aquí.</p></div><input type="file" id="bookFileInput" hidden multiple accept=".pdf,.txt,.md,.png,.jpg,.jpeg,.webp,.doc,.docx,.ppt,.pptx,.xls,.xlsx"></section><section class="card section-gap">${cardHead('Mis esquemas y resúmenes')} ${items.length?`<div class="file-list">${items.map(f=>`<div class="file-entry"><div class="file-type">${esc((f.name.split('.').pop()||'FILE').slice(0,4).toUpperCase())}</div><div class="row-main"><div class="row-title">${esc(f.name)}</div><div class="row-sub">${new Date(f.addedAt).toLocaleDateString('es-ES')} · ${formatBytes(f.size)}</div></div><button class="button small" data-action="open-book-file" data-id="${f.id}">Abrir</button><button class="icon-btn" data-action="download-book-file" data-id="${f.id}" title="Descargar">↓</button><button class="icon-btn" data-action="delete-book-file" data-id="${f.id}" title="Eliminar">×</button></div>`).join('')}`:empty('Este libro todavía está vacío','Pulsa «Adjuntar archivo» para guardar tu primer esquema o resumen.')}</section><section class="card section-gap">${cardHead('Escribe un resumen aquí',`<button class="button primary small" data-action="save-book-note">Guardar resumen</button>`)}<div class="field"><label>Título del resumen</label><input id="bookNoteTitle" placeholder="Ej. Tema 3: La Edad Moderna"></div><div class="field"><label>Contenido</label><textarea id="bookNoteText" rows="7" placeholder="Escribe o pega aquí tus apuntes. Puedes editarlo cuando quieras."></textarea></div></section>`}
function formatBytes(n){if(!n)return '0 B';const u=['B','KB','MB','GB'],i=Math.min(3,Math.floor(Math.log(n)/Math.log(1024)));return `${(n/1024**i).toFixed(i?1:0)} ${u[i]}`}
function renderReview(){let cards=state.flashcards;let current=cards.length?cards[flashcardIndex%cards.length]:null;return `${header('REPASO ACTIVO','Tarjetas de memoria','Crea preguntas para memorizar conceptos, fechas y personajes.',`<button class="button" data-action="start-quiz">▣ Hacer mini test</button><button class="button primary" data-action="new-flashcard">＋ Crear tarjeta</button>`)}<div class="grid two"><section class="card">${cardHead('Practica tus tarjetas')} ${current?`<div class="flashcard" id="flashcardFace"><small>${flashcardIndex+1} de ${cards.length}</small><h2>${esc(current.question)}</h2><p id="flashcardAnswer" hidden>${esc(current.answer)}</p><button class="button primary" data-action="flip-flashcard">Mostrar respuesta</button></div><div class="flashcard-nav"><button class="button" data-action="prev-flashcard">← Anterior</button><button class="button" data-action="next-flashcard">Siguiente →</button></div>`:empty('Aún no tienes tarjetas','Crea preguntas y respuestas para practicar.')}</section><section class="card">${cardHead('Tu colección')}<p class="muted">${cards.length} tarjetas guardadas</p>${cards.length?cards.map(c=>`<div class="file-entry"><div class="row-main"><b>${esc(c.question)}</b><div class="row-sub">${esc(c.answer.slice(0,100))}</div></div><button class="icon-btn" data-action="delete-flashcard" data-id="${c.id}">×</button></div>`).join(''):empty('Empieza poco a poco','Una tarjeta por cada idea importante es un buen comienzo.')}</section></div>`}
function startQuiz(){if(state.flashcards.length<2){toast('Crea al menos dos tarjetas para preparar un mini test.',true);return}const target=state.flashcards[Math.floor(Math.random()*state.flashcards.length)],others=state.flashcards.filter(c=>c.id!==target.id).sort(()=>Math.random()-.5).slice(0,3),options=[target,...others].sort(()=>Math.random()-.5);openModal('Mini test',`<p class="muted">Elige la respuesta correcta.</p><h3 class="quiz-question">${esc(target.question)}</h3><div class="quiz-options">${options.map((o,i)=>`<button type="button" class="button quiz-option" data-action="quiz-answer" data-correct="${o.id===target.id}">${esc(o.answer)}</button>`).join('')}</div><div id="quizFeedback" class="quiz-feedback" hidden></div>`,()=>true,'Cerrar test')};function flashcardModal(){openModal('Crear tarjeta de memoria',`${field('Pregunta','question','','text',{required:true,full:true})}${field('Respuesta','answer','','textarea',{required:true,full:true})}`,fd=>{let question=String(fd.get('question')||'').trim(),answer=String(fd.get('answer')||'').trim();if(!question||!answer){toast('Completa la pregunta y la respuesta.',true);return false}state.flashcards.push({id:uid(),question,answer});save();render();toast('Tarjeta creada')})}
function newSubjectModal(){openModal('Nueva asignatura',field('Nombre de la asignatura','subject','','text',{required:true}),fd=>{let sub=String(fd.get('subject')||'').trim();if(!sub)return false;if(!SUBJECTS.includes(sub))SUBJECTS.push(sub);if(!state.books[sub])state.books[sub]=[];selectedBookSubject=sub;save();page='shelf';render();setTimeout(()=>{page='book';render()},0);toast('Asignatura añadida')})}
function attachBookFiles(files){if(!files||!files.length)return;const sub=selectedBookSubject;state.books[sub]=state.books[sub]||[];let queue=[...files],done=0;queue.forEach(file=>{if(file.size>8*1024*1024){toast(`${file.name} supera el límite recomendado de 8 MB.`,true);done++;return}const reader=new FileReader();reader.onload=()=>{state.books[sub].push({id:uid(),name:file.name,size:file.size,type:file.type,data:reader.result,addedAt:new Date().toISOString()});done++;if(done===queue.length){save();render();toast('Archivos guardados en '+sub)}};reader.onerror=()=>{done++;toast('No se pudo leer '+file.name,true)};reader.readAsDataURL(file)})}
function openBookFile(id,download=false){let f=(state.books[selectedBookSubject]||[]).find(x=>x.id===id);if(!f)return;const a=document.createElement('a');a.href=f.data;a.download=f.name;a.target='_blank';if(download){document.body.appendChild(a);a.click();a.remove();return}if(f.type.startsWith('text/')||/\.(txt|md)$/i.test(f.name)){openModal(esc(f.name),`<pre class="text-preview">${esc(decodeURIComponent(escape(atob((f.data.split(',')[1]||'')))))}</pre>`,()=>true,'Cerrar');return}const win=window.open();if(win){win.document.write(`<title>${esc(f.name)}</title><iframe title="${esc(f.name)}" src="${f.data}" style="border:0;width:100%;height:100vh"></iframe>`);win.document.close()}else{document.body.appendChild(a);a.click();a.remove()}}
function renderSettings(){return `${header('A TU MANERA','Ajustes y copias de seguridad','Personaliza tu espacio y mantén tus datos a salvo.')}
<div class="grid two"><section class="card">${cardHead('Personalización')}<div class="field"><label>Nombre de bienvenida</label><input id="profileName" value="${esc(state.profile.name)}" maxlength="50"></div><div class="field"><label>Frase motivadora</label><textarea id="profileQuote" maxlength="180">${esc(state.profile.quote)}</textarea></div><div class="setting-row"><div><b>Mostrar frase motivadora</b><small>En la pantalla Mi día.</small></div><input type="checkbox" class="toggle" id="quoteOn" ${state.settings.quoteOn?'checked':''}></div><div class="setting-row"><div><b>Aspecto de la aplicación</b><small>Elige el tema que te resulte más cómodo.</small></div><select id="themeSelect" style="width:auto"><option value="light" ${state.settings.theme==='light'?'selected':''}>Claro</option><option value="dark" ${state.settings.theme==='dark'?'selected':''}>Suave oscuro</option></select></div><div class="setting-row"><div><b>Color de fondo</b><small>Cambia el ambiente de tu espacio.</small></div><select id="backgroundSelect" style="width:auto">${BACKGROUNDS.map(([id,label])=>`<option value="${id}" ${state.settings.background===id?'selected':''}>${label}</option>`).join('')}</select></div><div class="setting-row"><div><b>Primer día de la semana</b><small>Preferencia de calendario.</small></div><select id="weekStart" style="width:auto"><option value="1" ${state.settings.weekStart===1?'selected':''}>Lunes</option><option value="0" ${state.settings.weekStart===0?'selected':''}>Domingo</option></select></div><button class="button primary" data-action="save-profile" style="margin-top:15px">Guardar preferencias</button></section>
<section class="card">${cardHead('Temporizador Pomodoro')}<div class="form-grid"><div class="field"><label>Estudio (minutos)</label><input type="number" id="pomStudy" min="1" max="180" value="${state.settings.pomodoroStudy}"></div><div class="field"><label>Descanso corto (minutos)</label><input type="number" id="pomBreak" min="1" max="60" value="${state.settings.pomodoroBreak}"></div><div class="field"><label>Descanso largo (minutos)</label><input type="number" id="pomLong" min="1" max="90" value="${state.settings.longBreak}"></div><div class="field"><label>Descanso largo cada (sesiones)</label><input type="number" id="pomEvery" min="2" max="12" value="${state.settings.longBreakEvery}"></div></div><button class="button primary" data-action="save-pomodoro">Guardar temporizador</button><div class="setting-row" style="margin-top:15px"><div><b>Notificaciones del navegador</b><small>Solo se activan con tu permiso. La web debe estar abierta para avisos fiables.</small></div><input type="checkbox" class="toggle" id="notificationsOn" ${state.settings.notifications?'checked':''}></div><button class="button small" data-action="enable-notifications">Configurar permiso</button></section></div>
<section class="card section-gap">${cardHead('Datos y copias de seguridad')}<div class="setting-row"><div><b>Exportar copia de seguridad</b><small>Descarga tareas, hábitos, historial, notas, horario y preferencias en JSON.</small></div><button class="button" data-action="export">↓ Exportar JSON</button></div><div class="setting-row"><div><b>Importar una copia</b><small>El archivo se valida antes de restaurarlo. Se te pedirá confirmación porque sustituye los datos actuales.</small></div><button class="button" data-action="import">↑ Elegir archivo</button><input type="file" id="importFile" accept=".json,application/json" hidden></div><div class="setting-row"><div><b>Restaurar ajustes iniciales</b><small>Restablece nombre, tema y temporizador sin borrar tareas, notas ni hábitos.</small></div><button class="button" data-action="reset-settings">Restaurar ajustes</button></div><div class="setting-row"><div><b>Restaurar horario original</b><small>Vuelve a las asignaturas y horas de la instalación inicial.</small></div><button class="button" data-action="reset-schedule">Restaurar horario</button></div><div class="setting-row"><div><b>Borrar todos los datos</b><small>Esta acción elimina los datos guardados en este navegador. Exporta una copia antes si quieres conservarlos.</small></div><button class="button danger" data-action="wipe">Borrar datos</button></div><div class="notice" style="margin-top:15px">Los datos se guardan localmente en este navegador. No se sincronizan entre dispositivos y pueden perderse si se borran los datos del navegador. La copia JSON es tu forma de respaldo.</div></section>
<section class="card section-gap">${cardHead('Acceso rápido con NFC')}<p class="muted" style="font-size:12px;line-height:1.7">Cuando publiques esta web en una dirección HTTPS, puedes escribir esa URL en una etiqueta NFC con una app de escritura NFC. La etiqueta solo guarda el enlace: no contiene ni sincroniza tus tareas, notas ni hábitos.</p><div class="notice">Consulta el README incluido en el proyecto para instrucciones paso a paso de publicación y configuración NFC.</div></section>`}
function render(){document.body.classList.toggle('dark',state.settings.theme==='dark');document.body.dataset.background=state.settings.background||'beige';$('#todayLabel').textContent=new Date().toLocaleDateString('es-ES',{day:'numeric',month:'short'});$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page||(page==='book'&&b.dataset.page==='shelf')));const views={today:renderToday,calendar:renderCalendar,tasks:renderTasks,habits:renderHabits,study:renderStudy,grades:renderGrades,stats:renderStats,schedule:renderSchedule,settings:renderSettings,shelf:renderShelf,book:renderBook,review:renderReview};$('#pageContent').innerHTML=(views[page]||renderToday)();updateTimerDisplay();if(!state.profile.setupComplete)showOnboarding()}
function navigate(p){page=p;render();window.scrollTo({top:0,behavior:'smooth'})}
function openModal(title,body,onSave,saveLabel='Guardar'){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><button class="modal-close" data-action="modal-close" aria-label="Cerrar">×</button><h2>${title}</h2><form id="modalForm">${body}<div class="modal-actions"><button type="button" class="button" data-action="modal-close">Cancelar</button><button type="submit" class="button primary">${saveLabel}</button></div></form></section></div>`;root.querySelector('[data-action="modal-close"]').focus();root.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});root.querySelector('#modalForm').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget);if(onSave(fd)===false)return;closeModal()})}
function closeModal(){$('#modalRoot').innerHTML=''}
function field(label,name,value='',type='text',opts={}){let required=opts.required?'required':'',placeholder=opts.placeholder||'',min=opts.min!==undefined?`min="${opts.min}"`:'',max=opts.max!==undefined?`max="${opts.max}"`:'',extra=opts.extra||'';return `<div class="field ${opts.full?'full':''}"><label>${label}</label>${type==='textarea'?`<textarea name="${name}" ${required} maxlength="${opts.maxlength||1000}" placeholder="${placeholder}">${esc(value)}</textarea>`:type==='select'?`<select name="${name}" ${required}>${opts.options.map(o=>`<option value="${esc(o[0])}" ${String(value)===String(o[0])?'selected':''}>${esc(o[1])}</option>`).join('')}</select>`:`<input type="${type}" name="${name}" value="${esc(value)}" ${required} ${min} ${max} placeholder="${placeholder}" ${extra}>`}</div>`}
function taskForm(t={},date=''){let values={title:t.title||'',type:t.type||'task',subject:t.subject||'',date:t.date||date||'',time:t.time||'',priority:t.priority||'medium',status:t.status||'pending',description:t.description||'',estimate:t.estimate||'',reminder:t.reminder!==false};return `<div class="form-grid">${field('Título','title',values.title,'text',{required:true,full:true,placeholder:'Ej. Repasar el tema 3'})}${field('Tipo','type',values.type,'select',{options:[['task','Tarea'],['homework','Deberes'],['exam','Examen'],['delivery','Entrega'],['project','Proyecto'],['presentation','Presentación'],['event','Evento escolar'],['other','Otro']]})}${field('Asignatura','subject',values.subject,'select',{options:[['','Sin asignatura'],...subjectNames().map(s=>[s,s])]})}${field('Fecha','date',values.date,'date')}${field('Hora (opcional)','time',values.time,'time')}${field('Prioridad','priority',values.priority,'select',{options:[['low','Baja'],['medium','Media'],['high','Alta']]})}${field('Estado','status',values.status,'select',{options:[['pending','Pendiente'],['inprogress','En curso'],['completed','Completado']]})}${field('Tiempo estimado (min)','estimate',values.estimate,'number',{min:0,max:10000})}${field('Descripción / notas','description',values.description,'textarea',{full:true})}<div class="field full"><label><input type="checkbox" name="reminder" ${values.reminder?'checked':''} style="accent-color:var(--pink-dark)"> Recordatorio dentro de la aplicación</label></div></div>`}
function saveTaskForm(fd,id){let title=String(fd.get('title')||'').trim();if(!title){toast('Escribe un título para el elemento.',true);return false}let d={id:id||uid(),title,type:fd.get('type'),subject:fd.get('subject')||'',date:fd.get('date')||'',time:fd.get('time')||'',priority:fd.get('priority')||'medium',status:fd.get('status')||'pending',description:String(fd.get('description')||'').trim(),estimate:fd.get('estimate')?Number(fd.get('estimate')):null,reminder:fd.has('reminder'),updatedAt:new Date().toISOString()};if(id){let i=state.tasks.findIndex(x=>x.id===id);if(i>=0)state.tasks[i]=d}else state.tasks.push(d);save();render();toast(id?'Elemento actualizado':'Elemento añadido');return true}
function taskModal(id,date){let t=id?state.tasks.find(x=>x.id===id):null;openModal(t?'Editar elemento':'Añadir elemento',taskForm(t||{},date||''),fd=>saveTaskForm(fd,id))}
function habitModal(id){let h=id?state.habits.find(x=>x.id===id):null;openModal(h?'Editar hábito':'Nuevo hábito',field('Nombre del hábito','name',h?.name||'','text',{required:true,full:true,placeholder:'Ej. Estirar 5 minutos'}),fd=>{let name=String(fd.get('name')||'').trim();if(!name){toast('Escribe un nombre.',true);return false}if(h)h.name=name;else state.habits.push({id:uid(),name,active:true});save();render();toast(h?'Hábito actualizado':'Hábito creado')})}
function gradeModal(id){let g=id?state.grades.find(x=>x.id===id):null;let subjectOpts=[...new Set([...SUBJECTS,...state.grades.map(x=>x.subject)])].filter(Boolean);let body=`<div class="form-grid">${field('Asignatura','subject',g?.subject||'','select',{required:true,options:[['','Selecciona…'],...subjectOpts.map(s=>[s,s])]})}${field('Actividad','title',g?.title||'','text',{required:true})}${field('Nota obtenida','score',g?.score??'','number',{required:true,min:0,extra:'step="any"'})}${field('Nota máxima','max',g?.max??10,'number',{required:true,min:.01,extra:'step="any"'})}${field('Fecha','date',g?.date||todayISO(),'date',{required:true})}${field('Comentarios','comments',g?.comments||'','textarea',{full:true})}</div>`;openModal(g?'Editar nota':'Añadir nota',body,fd=>{let score=Number(fd.get('score')),max=Number(fd.get('max'));if(!fd.get('subject')||!String(fd.get('title')).trim()||!Number.isFinite(score)||!Number.isFinite(max)||max<=0||score<0||score>max){toast('Revisa la asignatura y las notas: la nota debe estar entre 0 y la máxima.',true);return false}let obj={id:id||uid(),subject:fd.get('subject'),title:String(fd.get('title')).trim(),score,max,date:fd.get('date')||todayISO(),comments:String(fd.get('comments')||'').trim()};if(g)state.grades=state.grades.map(x=>x.id===id?obj:x);else state.grades.push(obj);save();render();toast(g?'Nota actualizada':'Nota registrada')})}
function toggleTask(id){let t=state.tasks.find(t=>t.id===id);if(t){t.status=t.status==='completed'?'pending':'completed';save();render()}}
function toggleHabit(id){let logs=state.habitLogs[todayISO()]||(state.habitLogs[todayISO()]=[]);state.habitLogs[todayISO()]=logs.includes(id)?logs.filter(x=>x!==id):[...logs,id];save();render()}
function confirmAction(title,msg,callback){openModal(title,`<p style="font-size:13px;line-height:1.7;color:var(--muted)">${msg}</p>`,()=>{callback();return true},'Confirmar')}
function deleteBy(collection,id,label){let item=state[collection].find(x=>x.id===id);if(!item)return;confirmAction('Eliminar '+label,`¿Seguro que quieres eliminar «${esc(item.title||item.name)}»? Esta acción no se puede deshacer.`,()=>{state[collection]=state[collection].filter(x=>x.id!==id);save();render();toast(label+' eliminado')})}
function setTimerDuration(sec,mode='study'){state.timer.mode=mode;state.timer.duration=sec;state.timer.remaining=sec;state.timer.running=false;state.timer.startedAt=null;state.timer.sessionStart=null;save()}
function timerStart(){let t=state.timer;if(t.running){t.remaining=Math.max(0,t.remaining-Math.floor((Date.now()-t.startedAt)/1000));t.running=false;t.startedAt=null;save();render();return}if(t.remaining<=0)t.remaining=t.duration;t.running=true;t.startedAt=Date.now();if(!t.sessionStart)t.sessionStart=Date.now();save();render();ensureTimerInterval()}
function ensureTimerInterval(){if(timerInterval)clearInterval(timerInterval);timerInterval=setInterval(()=>{if(!state.timer.running)return;let t=state.timer,remain=t.remaining-Math.floor((Date.now()-t.startedAt)/1000);if(remain<=0){t.remaining=0;t.running=false;t.startedAt=null;finishTimer();}else updateTimerDisplay()},250)}
function updateTimerDisplay(){let el=$('#timerFace');if(!el)return;let t=state.timer,remain=t.running&&t.startedAt?Math.max(0,t.remaining-Math.floor((Date.now()-t.startedAt)/1000)):t.remaining;el.textContent=`${String(Math.floor(remain/60)).padStart(2,'0')}:${String(remain%60).padStart(2,'0')}`;let cap=$('#timerCaption');if(cap)cap.textContent=t.running?'Sesión en curso':remain===0?'Sesión finalizada':t.mode==='study'?'Todo listo para concentrarte':'Tómate un respiro'}
function finishTimer(){let t=state.timer;if(t.mode==='study'){let seconds=Math.max(0,Math.round((Date.now()-(t.sessionStart||Date.now()))/1000));state.sessions.push({id:uid(),date:todayISO(),seconds:Math.min(seconds,t.duration+2),subject:t.subject,mode:'study'});t.sessionsCount++;let long=t.sessionsCount%Math.max(2,state.settings.longBreakEvery)===0;setTimerDuration((long?state.settings.longBreak:state.settings.pomodoroBreak)*60,long?'longbreak':'break');toast('¡Sesión completada! Tu tiempo se ha guardado.');if(state.settings.notifications&&'Notification'in window&&Notification.permission==='granted')new Notification('Mi Espacio',{body:'¡Sesión de estudio completada! Tómate un descanso.'})}else{setTimerDuration(state.settings.pomodoroStudy*60,'study');t.sessionStart=null;toast('Descanso terminado. ¿Lista para continuar?')}save();render();if(state.settings.notifications&&'Notification'in window&&Notification.permission==='granted')new Notification('Mi Espacio',{body:'El temporizador ha terminado.'})}
function exportData(){let blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`mi-espacio-copia-${todayISO()}.json`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Copia de seguridad descargada')}
function validBackup(x){if(!x||typeof x!=='object'||x.version!==1)return false;for(let k of ['tasks','habits','sessions','grades'])if(!Array.isArray(x[k]))return false;if(!x.profile||!x.settings||!x.schedule||typeof x.habitLogs!=='object')return false;if(!x.tasks.every(t=>t&&typeof t.id==='string'&&typeof t.title==='string'))return false;if(!x.habits.every(h=>h&&typeof h.id==='string'&&typeof h.name==='string'))return false;if(!x.grades.every(g=>g&&typeof g.id==='string'&&Number.isFinite(Number(g.score))&&Number(g.max)>0&&Number(g.score)>=0&&Number(g.score)<=Number(g.max)))return false;return true}
function importFile(file){if(!file)return;let reader=new FileReader();reader.onload=()=>{try{let x=JSON.parse(reader.result);if(!validBackup(x)){toast('El archivo no parece una copia válida de Mi Espacio.',true);return}confirmAction('Importar copia de seguridad','Se reemplazarán los datos actuales por los incluidos en el archivo. Esta acción no se puede deshacer. Te recomendamos exportar antes una copia de los datos actuales.',()=>{state={...defaultState(),...x,profile:{...defaultState().profile,...x.profile},settings:{...defaultState().settings,...x.settings},timer:{...defaultState().timer,...x.timer},schedule:x.schedule};save();render();toast('Copia restaurada correctamente')})}catch(e){toast('No se ha podido leer el JSON. Comprueba que el archivo sea válido.',true)}};reader.onerror=()=>toast('No se pudo leer el archivo.',true);reader.readAsText(file)}
function classModal(day,idx){let c=idx!==undefined?(state.schedule[day]||[])[idx]:null;let body=`<div class="form-grid">${field('Hora','time',c?.[0]||'08:15','time',{required:true})}${field('Nombre','name',c?.[1]||'','text',{required:true})}${field('Tipo','kind',c?.[2]||'class','select',{options:[['class','Clase'],['break','Recreo / descanso'],['activity','Actividad extraescolar']]})}</div>`;openModal(c?'Editar horario':'Añadir al horario',body,fd=>{let time=fd.get('time'),name=String(fd.get('name')||'').trim();if(!time||!name){toast('Indica una hora y un nombre.',true);return false}let arr=state.schedule[day]||(state.schedule[day]=[]);let item=[time,name,fd.get('kind')];if(idx!==undefined)arr[idx]=item;else arr.push(item);arr.sort((a,b)=>a[0].localeCompare(b[0]));save();render();toast('Horario actualizado')})}
function handleAction(el){let a=el.dataset.action,id=el.dataset.id;switch(a){
case'focus-mode':document.body.classList.toggle('focus-mode');toast(document.body.classList.contains('focus-mode')?'Modo concentración activado':'Modo concentración desactivado');break;case'sound-toggle':toggleAmbientSound(el);break;case'open-book':selectedBookSubject=el.dataset.subject;page='book';render();break;case'back-shelf':page='shelf';render();break;case'new-book-subject':newSubjectModal();break;case'attach-book-file':$('#bookFileInput')?.click();break;case'open-book-file':openBookFile(id,false);break;case'download-book-file':openBookFile(id,true);break;case'delete-book-file':confirmAction('Eliminar archivo','Este archivo se quitará de esta asignatura.',()=>{state.books[selectedBookSubject]=(state.books[selectedBookSubject]||[]).filter(f=>f.id!==id);save();render();toast('Archivo eliminado')});break;case'save-book-note':{let title=$('#bookNoteTitle').value.trim(),content=$('#bookNoteText').value.trim();if(!title||!content){toast('Escribe un título y el contenido del resumen.',true);break}state.books[selectedBookSubject]=state.books[selectedBookSubject]||[];state.books[selectedBookSubject].push({id:uid(),name:title+'.txt',size:new Blob([content]).size,type:'text/plain',data:'data:text/plain;base64,'+btoa(unescape(encodeURIComponent(content))),addedAt:new Date().toISOString()});save();render();toast('Resumen guardado');break}case'start-quiz':startQuiz();break;case'quiz-answer':{const correct=el.dataset.correct==='true',feedback=$('#quizFeedback');if(feedback){feedback.hidden=false;feedback.textContent=correct?'¡Correcto! Muy bien. ✨':'No pasa nada: repasa la tarjeta y vuelve a intentarlo.';feedback.className='quiz-feedback '+(correct?'good':'try-again');$$('.quiz-option').forEach(b=>{b.disabled=true;if(b.dataset.correct==='true')b.classList.add('quiz-correct')})}break}case'new-flashcard':flashcardModal();break;case'flip-flashcard':{let a=$('#flashcardAnswer');if(a){a.hidden=!a.hidden;el.textContent=a.hidden?'Mostrar respuesta':'Ocultar respuesta'}break}case'prev-flashcard':flashcardIndex=Math.max(0,flashcardIndex-1);render();break;case'next-flashcard':flashcardIndex=(flashcardIndex+1)%Math.max(1,state.flashcards.length);render();break;case'delete-flashcard':confirmAction('Eliminar tarjeta','¿Quieres eliminar esta tarjeta?',()=>{state.flashcards=state.flashcards.filter(c=>c.id!==id);flashcardIndex=0;save();render();toast('Tarjeta eliminada')});break;case'new-task':taskModal(null,el.dataset.date||'');break;case'edit-task':taskModal(id);break;case'delete-task':deleteBy('tasks',id,'elemento');break;case'toggle-task':toggleTask(id);break;
case'select-date':selectedDate=el.dataset.date;render();break;case'prev-month':calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()-1,1);render();break;case'next-month':calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()+1,1);render();break;case'current-month':calendarDate=new Date();selectedDate=todayISO();render();break;
case'new-habit':habitModal();break;case'edit-habit':habitModal(id);break;case'delete-habit':deleteBy('habits',id,'hábito');break;case'toggle-habit':toggleHabit(id);break;case'habit-history':{let h=state.habits.find(x=>x.id===id);let days=Object.keys(state.habitLogs).filter(d=>(state.habitLogs[d]||[]).includes(id)).sort().reverse();openModal(`Historial: ${esc(h.name)}`,days.length?`<div>${days.map(d=>`<div class="setting-row"><b>${fmtDate(d,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</b><span class="pill done">Completado</span></div>`).join('')}</div>`:empty('Sin registros todavía','Marca el hábito como realizado para guardar el día.'),()=>true,'Cerrar');break}
case'timer-toggle':timerStart();break;case'timer-reset':state.timer.running=false;state.timer.startedAt=null;state.timer.sessionStart=null;state.timer.remaining=state.timer.duration;save();render();break;case'timer-apply':{let m=Number($('#timerMinutes')?.value),sub=$('#timerSubject')?.value||'';if(!Number.isFinite(m)||m<1||m>180){toast('Elige una duración entre 1 y 180 minutos.',true);break}setTimerDuration(m*60,state.timer.mode);state.timer.subject=sub;save();render();toast('Temporizador actualizado');break}
case'new-grade':gradeModal();break;case'edit-grade':gradeModal(id);break;case'delete-grade':deleteBy('grades',id,'nota');break;
case'schedule-day':selectedScheduleDay=el.dataset.day;render();break;case'new-class':classModal(selectedScheduleDay);break;case'edit-class':classModal(el.dataset.day,Number(el.dataset.index));break;case'delete-class':{let d=el.dataset.day,i=Number(el.dataset.index);confirmAction('Eliminar del horario','¿Quieres quitar esta clase o actividad del horario?',()=>{state.schedule[d].splice(i,1);save();render();toast('Horario actualizado')});break}
case'reset-schedule':confirmAction('Restaurar horario original','Se reemplazará el horario personalizado por el horario inicial. No se borrarán tareas, notas ni hábitos.',()=>{state.schedule=JSON.parse(JSON.stringify(SCHEDULE));save();render();toast('Horario original restaurado')});break;
case'save-profile':{state.profile.name=$('#profileName').value.trim()||'Estudiante';state.profile.setupComplete=true;state.profile.quote=$('#profileQuote').value.trim();state.settings.quoteOn=$('#quoteOn').checked;state.settings.theme=$('#themeSelect').value;state.settings.background=$('#backgroundSelect').value;state.settings.weekStart=Number($('#weekStart').value);save();render();toast('Preferencias guardadas');break}
case'save-pomodoro':{let a=Number($('#pomStudy').value),b=Number($('#pomBreak').value),c=Number($('#pomLong').value),d=Number($('#pomEvery').value);if(a<1||a>180||b<1||b>60||c<1||c>90||d<2||d>12||![a,b,c,d].every(Number.isFinite)){toast('Revisa las duraciones del temporizador.',true);break}state.settings.pomodoroStudy=a;state.settings.pomodoroBreak=b;state.settings.longBreak=c;state.settings.longBreakEvery=d;if(!state.timer.running){setTimerDuration(a*60,'study')}save();render();toast('Configuración Pomodoro guardada');break}
case'enable-notifications':if(!('Notification'in window)){toast('Este navegador no admite notificaciones.',true);break}Notification.requestPermission().then(p=>{state.settings.notifications=p==='granted';save();render();toast(p==='granted'?'Notificaciones activadas':'No se concedió permiso')});break;
case'export':exportData();break;case'import':$('#importFile').click();break;case'reset-settings':confirmAction('Restaurar ajustes','Se restaurarán nombre, frase, tema y temporizador. Las tareas, notas, hábitos y sesiones se conservarán.',()=>{let d=defaultState();state.profile=d.profile;state.settings=d.settings;state.timer=d.timer;save();render();toast('Ajustes iniciales restaurados')});break;
case'wipe':confirmAction('Borrar todos los datos','Se eliminarán permanentemente los datos guardados por Mi Espacio en este navegador, incluido el horario personalizado. Exporta antes una copia si quieres conservarlos.',()=>{state=defaultState();save();page='today';render();toast('Datos borrados')});break;case'modal-close':closeModal();break;
}}
document.addEventListener('click',e=>{let nav=e.target.closest('[data-page]');if(nav){e.preventDefault();navigate(nav.dataset.page);return}let act=e.target.closest('[data-action]');if(act){if(act.dataset.action==='toggle-task'||act.dataset.action==='toggle-habit'){handleAction(act);return}handleAction(act)}});
document.addEventListener('change',e=>{if(e.target.id==='taskFilterType'){window.taskFilterType=e.target.value;render()}if(e.target.id==='taskFilterStatus'){window.taskFilterStatus=e.target.value;render()}if(e.target.id==='taskFilterSubject'){window.taskFilterSubject=e.target.value;render()}if(e.target.id==='gradeFilter'){window.gradeFilter=e.target.value;render()}if(e.target.id==='importFile'){importFile(e.target.files[0]);e.target.value=''}if(e.target.id==='bookFileInput'){attachBookFiles(e.target.files);e.target.value=''}if(e.target.id==='notificationsOn'&&e.target.checked)handleAction({dataset:{action:'enable-notifications'}});if(e.target.id==='notificationsOn'&&!e.target.checked){state.settings.notifications=false;save();toast('Notificaciones desactivadas')}});
document.addEventListener('input',e=>{if(e.target.id==='taskSearch'){let p=e.target.selectionStart;window.taskSearch=e.target.value;let val=e.target.value;render();let n=$('#taskSearch');n.focus();n.setSelectionRange(p,p)}});
$('#avatarBtn').addEventListener('click',()=>{navigate('settings');setTimeout(()=>$('#profileName')?.focus(),20)});
window.addEventListener('storage',e=>{if(e.key==='miEspacioData'){state=loadState();render()}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.timer.running){let t=state.timer,remain=t.remaining-Math.floor((Date.now()-t.startedAt)/1000);if(remain<=0){t.remaining=0;t.running=false;t.startedAt=null;finishTimer()}else updateTimerDisplay()}});
if(state.timer.running){let t=state.timer,remain=t.remaining-Math.floor((Date.now()-t.startedAt)/1000);if(remain<=0){t.remaining=0;t.running=false;t.startedAt=null;finishTimer()}else ensureTimerInterval()}
render();
})();